<script setup>
import { useCustomerPresentation } from '../../Composables/customerPresentation';
const { customerText } = useCustomerPresentation();

import {Head,Link,useForm} from '@inertiajs/vue3';import CustomerShell from '../../Components/CustomerShell.vue';const props=defineProps({email:String,token:String});const form=useForm({email:props.email??'',token:props.token??'',password:'',password_confirmation:''});const submit=()=>{if(form.processing)return;form.post('/reset-password',{onFinish:()=>form.reset('password','password_confirmation')})};
</script><template><Head :title="customerText(&quot;pages.auth.resetpassword.attribute.title.db424161&quot;, &quot;Kata sandi baru&quot;)"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="submit"><p class="lf-eyebrow">{{ customerText("pages.auth.resetpassword.7d1d4c9a", "Keamanan akun") }}</p><h1>{{ customerText("pages.auth.resetpassword.db424161", "Kata sandi baru") }}</h1><p>{{ customerText("pages.auth.resetpassword.b4644f49", "Gunakan minimal 12 karakter.") }}</p><div class="grid gap-3"><label class="text-[10px] font-semibold text-white/70">{{ customerText("pages.auth.resetpassword.43352167", "Email") }}<input v-model="form.email" type="email" name="email" autocomplete="username" :placeholder="customerText(&quot;pages.auth.resetpassword.attribute.placeholder.a06a6645&quot;, &quot;Masukkan email akun&quot;)" :aria-invalid="Boolean(form.errors.email)" required><span v-if="form.errors.email" role="alert" class="mt-1 block text-xs text-red-300">{{form.errors.email}}</span></label><label class="text-[10px] font-semibold text-white/70">{{ customerText("pages.auth.resetpassword.db424161", "Kata sandi baru") }}<input v-model="form.password" type="password" name="password" autocomplete="new-password" :placeholder="customerText(&quot;pages.auth.resetpassword.attribute.placeholder.d3d2f4b0&quot;, &quot;Minimal 12 karakter&quot;)" :aria-invalid="Boolean(form.errors.password)" minlength="12" required><span v-if="form.errors.password" role="alert" class="mt-1 block text-xs text-red-300">{{form.errors.password}}</span></label><label class="text-[10px] font-semibold text-white/70">{{ customerText("pages.auth.resetpassword.9c34c763", "Ulangi kata sandi") }}<input v-model="form.password_confirmation" type="password" name="password_confirmation" autocomplete="new-password" :placeholder="customerText(&quot;pages.auth.resetpassword.attribute.placeholder.7cd33da1&quot;, &quot;Masukkan ulang kata sandi&quot;)" :aria-invalid="Boolean(form.errors.password_confirmation)" required><span v-if="form.errors.password_confirmation" role="alert" class="mt-1 block text-xs text-red-300">{{form.errors.password_confirmation}}</span></label><p v-if="form.errors.token" role="alert" class="text-xs text-red-300">{{form.errors.token}}</p><button type="submit" class="lf-primary w-full" :disabled="form.processing">{{form.processing?'Menyimpan…':'Simpan kata sandi'}}</button></div><div class="lf-auth-links"><Link href="/forgot-password">{{ customerText("pages.auth.resetpassword.c3e824b3", "Minta tautan baru") }}</Link><Link href="/login">{{ customerText("pages.auth.resetpassword.38bcaaa5", "Kembali ke masuk") }}</Link></div></form></main></CustomerShell></template>